class SensorCommand(BaseModel):
    sensor_type: str
    mode: str
    params: dict = {}

class WeaponCommand(BaseModel):
    weapon: str
    target: str
    fire: bool = False

@app.post('/sensors/radar')
async def radar(cmd: SensorCommand):
    if cmd.sensor_type not in RADAR_TYPES:
        return {'error': 'Unknown radar type'}
    return {'status': 'radar_active', 'type': cmd.sensor_type, 'mode': cmd.mode,
            'data': {'contacts': random.randint(0, 20), 'range': random.randint(1, 100), 'bearing': random.randint(0, 360)}}

