@app.post('/weapons/fire')
async def fire_weapon(cmd: WeaponCommand):
    if cmd.weapon not in WEAPONS:
        return {'error': 'Unknown weapon'}
    weapon = WEAPONS[cmd.weapon]
    if cmd.fire:
        return {'status': 'fired', 'weapon': cmd.weapon, 'target': cmd.target, 'specs': weapon, 'timestamp': 'now'}
    return {'status': 'armed', 'weapon': cmd.weapon, 'specs': weapon}

@app.get('/weapons')
async def list_weapons():
    return {'weapons': list(WEAPONS.keys())}

@app.get('/weapons/{weapon}')
async def get_weapon(weapon: str):
    if weapon not in WEAPONS:
        return {'error': 'Weapon not found'}
    return WEAPONS[weapon]

